import Foundation
import Network
import Security
import CryptoKit
import Synchronization

/// The show-notes view tests' HTTPS server on 127.0.0.1. The notes are a page from `https://127.0.0.1`, so their
/// subresources are tested over TLS, as a publisher's are. The certificates are generated by the view-test scheme's
/// pre-action (`Tools/shownotes-tls-fixture.sh`) into `.work`; nothing is trusted system-wide. Every response closes
/// its connection, so each request has its own connection, byte counts and disconnect.
final class ShownotesFixtureServer: @unchecked Sendable {
    enum Reply: Sendable {
        case body(Data, type: String, headers: [String: String] = [:])
        /// Headers declaring `body.count` bytes and the first `prefix` bytes of `body`; the rest waits for the test
        /// (`Exchange.release`, `Exchange.pace`).
        case held(Data, type: String, prefix: Int)
    }

    struct Identity: @unchecked Sendable {
        let identity: SecIdentity
        let fingerprint: Data

        /// `trusted` (the certificate the notes' test hook accepts) or `other` (a control it must reject).
        static func load(_ name: String) throws -> Identity {
            let folder = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
                .appendingPathComponent(".work/test-fixtures/shownotes-tls")
            guard let data = try? Data(contentsOf: folder.appendingPathComponent("\(name).p12")) else {
                throw FixtureMissing(description: "Run the view tests through their scheme (its pre-action runs Tools/shownotes-tls-fixture.sh)")
            }
            var items: CFArray?
            let status = SecPKCS12Import(data as CFData, [kSecImportExportPassphrase as String: "fixture"] as CFDictionary, &items)
            guard status == errSecSuccess, let item = (items as? [[String: Any]])?.first,
                  let value = item[kSecImportItemIdentity as String] else {
                throw FixtureMissing(description: "The \(name) fixture identity could not be read (\(status))")
            }
            let identity = value as! SecIdentity
            var certificate: SecCertificate?
            SecIdentityCopyCertificate(identity, &certificate)
            return Identity(identity: identity, fingerprint: Data(SHA256.hash(data: SecCertificateCopyData(certificate!) as Data)))
        }
    }
    struct FixtureMissing: Error, CustomStringConvertible { let description: String }

    /// One request's connection.
    final class Exchange: @unchecked Sendable {
        let path: String
        fileprivate let connection: NWConnection
        fileprivate let body: Data
        private let state = Mutex(State())
        private struct State {
            var accepted = 0, acceptedAtMark: Int?, disconnected = false, writeFailed = false, complete = false
        }
        fileprivate init(path: String, connection: NWConnection, body: Data) {
            self.path = path; self.connection = connection; self.body = body
        }
        /// Body bytes the client's socket accepted (sends that completed).
        var accepted: Int { state.withLock { $0.accepted } }
        var disconnected: Bool { state.withLock { $0.disconnected } }
        var writeFailed: Bool { state.withLock { $0.writeFailed } }
        var complete: Bool { state.withLock { $0.complete } }
        /// Bytes accepted since `mark()`.
        var acceptedSinceMark: Int { state.withLock { $0.accepted - ($0.acceptedAtMark ?? $0.accepted) } }
        func mark() { state.withLock { $0.acceptedAtMark = $0.accepted } }
        fileprivate func accept(_ count: Int) { state.withLock { $0.accepted += count } }
        fileprivate func disconnect() { state.withLock { $0.disconnected = true } }

        /// Sends the rest of the body; returns whether every write succeeded.
        @discardableResult func release() async -> Bool {
            let remaining = body.count - accepted
            guard remaining > 0 else { return true }
            let ok = await write(body.suffix(remaining), final: true)
            if ok { state.withLock { $0.complete = true } }
            return ok
        }

        /// Paced writes of the rest of the body, `chunk` bytes at a time, until a write fails or the body ends.
        func pace(chunk: Int = 16 * 1024, every interval: Duration = .milliseconds(5)) async {
            while accepted < body.count {
                let start = accepted
                let end = min(body.count, start + chunk)
                guard await write(body.subdata(in: start..<end), final: end == body.count) else { return }
                try? await Task.sleep(for: interval)
            }
            state.withLock { $0.complete = true }
        }

        /// Whether writes now fail (the client is gone). The first write after the client's close can still be
        /// accepted locally; the client's reset then fails the next ones.
        func writeFails(within limit: Duration = .seconds(5)) async -> Bool {
            let deadline = ContinuousClock.now + limit
            while ContinuousClock.now < deadline {
                if writeFailed || connection.state != .ready { return true }
                if !(await write(Data(count: 16 * 1024), final: false)) { return true }
                try? await Task.sleep(for: .milliseconds(20))
            }
            return false
        }

        private func write(_ data: Data, final: Bool) async -> Bool {
            await withCheckedContinuation { continuation in
                connection.send(content: data, contentContext: final ? .finalMessage : .defaultMessage, isComplete: true,
                                completion: .contentProcessed { [self] error in
                    if error == nil { accept(data.count) } else { state.withLock { $0.writeFailed = true } }
                    continuation.resume(returning: error == nil)
                })
            }
        }
    }

    private let listener: NWListener
    private let queue = DispatchQueue(label: "AntennaPodTests.ShownotesFixture")
    private let handler: @Sendable (String) -> Reply
    private let recorded = Mutex<[String]>([])
    private let held = Mutex<[Exchange]>([])
    private let connectionCount = Mutex(0)
    private let open = Mutex<[NWConnection]>([])

    var port: Int { Int(listener.port!.rawValue) }
    func url(_ path: String) -> String { "https://127.0.0.1:\(port)\(path)" }
    /// Requests whose path starts with `prefix`.
    func count(_ prefix: String) -> Int { recorded.withLock { $0.filter { $0.hasPrefix(prefix) }.count } }
    var requests: [String] { recorded.withLock { $0 } }
    /// TCP connections accepted, including any whose TLS handshake failed.
    var connections: Int { connectionCount.withLock { $0 } }
    func exchanges(_ prefix: String) -> [Exchange] { held.withLock { $0.filter { $0.path.hasPrefix(prefix) } } }

    private init(identity: Identity, handler: @escaping @Sendable (String) -> Reply) throws {
        let tls = NWProtocolTLS.Options()
        sec_protocol_options_set_local_identity(tls.securityProtocolOptions, sec_identity_create(identity.identity)!)
        let parameters = NWParameters(tls: tls, tcp: NWProtocolTCP.Options())
        parameters.requiredLocalEndpoint = .hostPort(host: "127.0.0.1", port: .any)
        listener = try NWListener(using: parameters)
        self.handler = handler
    }

    static func start(identity: Identity, handler: @escaping @Sendable (String) -> Reply) async throws -> ShownotesFixtureServer {
        let server = try ShownotesFixtureServer(identity: identity, handler: handler)
        server.listener.newConnectionHandler = { [weak server] connection in
            guard let server else { connection.cancel(); return }
            server.connectionCount.withLock { $0 += 1 }
            server.open.withLock { $0.append(connection) }
            connection.start(queue: server.queue)
            server.read(connection, accumulated: Data())
        }
        let resumed = Mutex(false)
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, Error>) in
            server.listener.stateUpdateHandler = { state in
                switch state {
                case .ready:
                    if !resumed.withLock({ let previous = $0; $0 = true; return previous }) { continuation.resume() }
                case .failed(let error):
                    if !resumed.withLock({ let previous = $0; $0 = true; return previous }) { continuation.resume(throwing: error) }
                default: break
                }
            }
            server.listener.start(queue: server.queue)
        }
        return server
    }

    func stop() {
        listener.cancel()
        for connection in open.withLock({ let all = $0; $0 = []; return all }) { connection.cancel() }
    }

    private func read(_ connection: NWConnection, accumulated: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 65_536) { [weak self] data, _, complete, error in
            guard let self else { connection.cancel(); return }
            let buffer = accumulated + (data ?? Data())
            guard let end = buffer.range(of: Data("\r\n\r\n".utf8)) else {
                if !complete, error == nil, buffer.count < 65_536 { self.read(connection, accumulated: buffer) }
                else { connection.cancel() }
                return
            }
            let line = String(decoding: buffer[..<end.lowerBound], as: UTF8.self).components(separatedBy: "\r\n")[0]
            let parts = line.split(separator: " ")
            guard parts.count == 3 else { connection.cancel(); return }
            let path = String(parts[1])
            recorded.withLock { $0.append(path) }
            switch handler(path) {
            case .body(let body, let type, let headers):
                connection.send(content: head(type: type, length: body.count, headers: headers) + body, contentContext: .finalMessage,
                                isComplete: true, completion: .contentProcessed { _ in })
            case .held(let body, let type, let prefix):
                let exchange = Exchange(path: path, connection: connection, body: body)
                held.withLock { $0.append(exchange) }
                watch(exchange)
                let first = body.prefix(prefix)
                connection.send(content: head(type: type, length: body.count, headers: [:]) + first, contentContext: .defaultMessage,
                                isComplete: true, completion: .contentProcessed { error in if error == nil { exchange.accept(first.count) } })
            }
        }
    }

    /// The client closing the connection (or it failing) is a disconnect.
    private func watch(_ exchange: Exchange) {
        exchange.connection.receive(minimumIncompleteLength: 1, maximumLength: 65_536) { [weak self] _, _, complete, error in
            if complete || error != nil { exchange.disconnect() } else { self?.watch(exchange) }
        }
    }

    private func head(type: String, length: Int, headers: [String: String]) -> Data {
        var output = "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Type: \(type)\r\nContent-Length: \(length)\r\n"
            + "Access-Control-Allow-Origin: *\r\n"
        let caching = headers.keys.contains { $0.lowercased() == "cache-control" }
        if !caching { output += "Cache-Control: no-store\r\n" }
        for (key, value) in headers { output += "\(key): \(value)\r\n" }
        return Data((output + "\r\n").utf8)
    }
}
